 private static final class TestTime implements SyntheticTaskLoop.Time {long at,elapsed=1000;String boot="SYNTHETIC-BOOT";TestTime(long at){this.at=at;}public Clock wall(){return Clock.fixed(Instant.ofEpochMilli(at),ZoneOffset.UTC);}public long elapsedMillis(){return elapsed;}public String bootId(){return boot;}}
 private void check(boolean ok){checks++;if(!ok)throw new IllegalStateException("LOOP_ASSERTION_"+checks);}
 private void denied(Runnable action,String reason){checks++;try{action.run();}catch(RuntimeException e){if(reason.equals(e.getMessage()))return;throw new IllegalStateException("UNEXPECTED:"+e.getMessage(),e);}throw new IllegalStateException("EXPECTED_"+reason);}
