 private String prepare(String n){try(ContactTaskStore s=open(n)){return s.importContact(input(1)).contact.id;}}
 private void write(String file,JSONObject value)throws Exception{AtomicFile f=new AtomicFile(new File(getFilesDir(),file));FileOutputStream out=null;try{out=f.startWrite();out.write(value.toString().getBytes(StandardCharsets.UTF_8));f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);throw e;}}
 private JSONObject state()throws Exception{File file=new File(getFilesDir(),STATE);if(!file.exists())return new JSONObject().put("purpose","SYNTHETIC_LOOP_FIXTURE_V1");if(file.length()>8192)throw new IllegalStateException("INVALID_LOOP_STATE");JSONObject s=new JSONObject(new String(java.nio.file.Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));if(!s.optString("purpose").equals("SYNTHETIC_LOOP_FIXTURE_V1"))throw new IllegalStateException("INVALID_LOOP_STATE");return s;}
 private SQLiteDatabase raw(String n){SQLiteDatabase db=SQLiteDatabase.openDatabase(getDatabasePath(n).getAbsolutePath(),null,SQLiteDatabase.OPEN_READWRITE);db.setForeignKeyConstraintsEnabled(false);return db;}
 private long number(String n,String sql){try(SQLiteDatabase db=raw(n);Cursor c=db.rawQuery(sql,null)){if(!c.moveToFirst())throw new IllegalStateException("NO_FIXTURE_ROW");return c.getLong(0);}}
 private void plan(ContactTaskStore s,String id){s.arrangePlan(id,1,1,s.getPlan().version,due(),clock(due()));}
 private void schemaThree(String n){String id=prepare(n);try(ContactTaskStore s=open(n)){plan(s,id);}try(SQLiteDatabase db=raw(n)){db.execSQL("DROP TABLE synthetic_attempt_events");db.execSQL("DROP TABLE synthetic_attempts");db.execSQL("UPDATE catalog_meta SET version=3");db.setVersion(3);}}
 private interface Call{String run();}
 private String[] race(Call a,Call b)throws Exception{CountDownLatch start=new CountDownLatch(1);String[] r=new String[2];Throwable[] errors=new Throwable[2];Call[] actions={a,b};Thread[] threads=new Thread[2];for(int i=0;i<2;i++){final int n=i;threads[i]=new Thread(()->{try{start.await();r[n]=actions[n].run();}catch(Throwable e){errors[n]=e;}});threads[i].start();}start.countDown();for(Thread t:threads){t.join(7000);if(t.isAlive())throw new IllegalStateException("LOOP_RACE_TIMEOUT");}for(Throwable e:errors)if(e!=null)throw new IllegalStateException("LOOP_RACE_FAILED",e);return r;}
